def cheapest_with_coupon(n, roads, src, dst):
    near = [[] for _ in range(n)]
    for a, b, cost in roads:
        near[a].append((b, cost))
        near[b].append((a, cost))
    best = [[None, None] for _ in range(n)]
    best[src][0] = 0
    heap = [(0, src, 0)]
    while heap:
        c, u, used = heapq.heappop(heap)
        if c > best[u][used]:
            continue
        if u == dst:
            return c
        for v, w in near[u]:
            if used:
                moves = [(1, w)]
            elif u == src or v == src:
                moves = [(0, w)]
            else:
                moves = [(0, w), (1, w // 2)]
            for k, step in moves:
                if best[v][k] is None or c + step < best[v][k]:
                    best[v][k] = c + step
                    heapq.heappush(heap, (c + step, v, k))
    return -1

