import heapq

def cheapest_with_coupon(n, roads, src, dst):
    near = [[] for _ in range(n)]
    for a, b, cost in roads:
        near[a].append((b, cost))
        near[b].append((a, cost))
    INF = float('inf')
    best = [[INF, INF] for _ in range(n)]
    best[src][0] = 0
    heap = [(0, src, 0)]
    while heap:
        c, u, k = heapq.heappop(heap)
        if c > best[u][k]:
            continue
        for v, w in near[u]:
            if c + w < best[v][k]:
                best[v][k] = c + w
                heapq.heappush(heap, (c + w, v, k))
            if k == 0 and u != src and v != src and c + w // 2 < best[v][1]:
                best[v][1] = c + w // 2
                heapq.heappush(heap, (c + w // 2, v, 1))
    if best[dst][0] == INF:
        return -1
    return best[dst][1] if best[dst][1] < INF else best[dst][0]

import heapq

def cheapest_with_coupon(n, roads, src, dst):
    def dijkstra(half):
        near = [[] for _ in range(n)]
        for i, (a, b, cost) in enumerate(roads):
            w = cost // 2 if i == half and src not in (a, b) else cost
            near[a].append((b, w))
            near[b].append((a, w))
        best = [None] * n
        best[src] = 0
        heap = [(0, src)]
        while heap:
            c, u = heapq.heappop(heap)
            if c > best[u]:
                continue
            for v, w in near[u]:
                if best[v] is None or c + w < best[v]:
                    best[v] = c + w
                    heapq.heappush(heap, (c + w, v))
        return best[dst]

    found = [d for d in (dijkstra(i) for i in range(-1, len(roads))) if d is not None]
    return min(found) if found else -1
